  // ---------- крупные дела после дефолта ----------
  const crane = (x, h, col) => R(x, GY - h, 2.4, h, col) + L(x + 1.2, GY - h + 2, x + 30, GY - h + 6, col, 1.4) + L(x + 1.2, GY - h + 2, x - 10, GY - h + 4, col, 1.2) + L(x + 28, GY - h + 6, x + 28, GY - h + 22, '#888', 0.4) + R(x - 12, GY - h + 3, 5, 4, '#555');
