      h += P('M188 66L192 2L196 66Z', '#8aa8c0') + R(191.4, -4, 1.2, 8, '#8aa8c0') + tower(150, 18, 40, '#6a8aa8', 441, 0.3) + tower(206, 16, 48, '#7a98b4', 443, 0.3) + tower(226, 14, 30, '#6a8aa8', 445, 0.3) + crane(130, 40, '#e3b341') + tarmac('#6a6470');
